style.css:
/* Applies only to Google search result pages */
@-moz-document domain("google.com") {
/* Background settings for the whole page */
    html, body {
        background: url("https://i.pinimg.com/736x/1f/c9/bd/1fc9bd96c85a4f9f37be2953171d3624.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Ensure search results and other main elements are readable */
    .rc, #search, .g, .srg, #rso, .bkWMgd {
        background-color: rgba(255, 255, 255, 0.85) !important; /* White with 85% opacity */
        border-radius: 8px;
        padding: 10px;
    }

    /* Adjust text color for readability */
    h3, .LC20lb, .IsZvec, .aCOpRe, .VwiC3b {
        color: #333333 !important; /* Dark text for contrast */
    }

    /* Exclude certain websites */
    a[href*="online.vinschool.edu.vn"], 
    a[href*="app.myimaths.com"], 
    a[href*="doctorfrostmaths.com"] {
        display: inline !important;
        background: none !important;
        color: inherit !important;
    }
}
